class OamKpiCalculationsException(Exception):
    pass


class DataNotAvailable(OamKpiCalculationsException):
    def __init__(self, message):
        self.message = message
        super(DataNotAvailable, self).__init__(self.message)

    def __repr__(self):
        return r"{}({})".format(type(self), self.message)


class IndicationPointDataNotAvailable(DataNotAvailable):
    def __init__(self, kpi):
        self.message = r"IndicationPoint({}) not available for KPI_NAME: {}".format(kpi.start_search_after, kpi.name)
        super(IndicationPointDataNotAvailable, self).__init__(self.message)


class StartPointDataNotAvailable(DataNotAvailable):
    def __init__(self, kpi, message=None):
        merged_message = r"StartPoint data not available for KPI_NAME: {}".format(kpi.name)
        if message:
            merged_message = "{}{}".format(merged_message, message)
        super(StartPointDataNotAvailable, self).__init__(merged_message)


class EndPointDataNotAvailable(DataNotAvailable):
    def __init__(self, kpi, message=None):
        merged_message = r"EndPoint data not available for KPI_NAME: {}".format(kpi.name)
        if message:
            merged_message = "{}{}".format(merged_message, message)
        super(EndPointDataNotAvailable, self).__init__(merged_message)
